import {moveData,stage,clamp} from './combat-rules.mjs';
export function survivalSupport(c,raw,targets){const r=c.r,m=moveData(raw),f=r.fighter;f.stages||={};r.cooldowns[r.slot]=m.healing?6:4;r.attackUntil=r.time+.4;r.attackFX.push({move:m,from:{x:r.x,y:r.y},to:{x:targets[0]&&m.target!==7?targets[0].x:r.x,y:targets[0]&&m.target!==7?targets[0].y:r.y},age:0});
 if(m.healing||m.slug==='rest'){r.hp=Math.min(r.max,r.hp+r.max*(m.slug==='rest'?1:(m.healing||50)/100));r.effects.push({x:r.x,y:r.y-25,life:.7,max:.7,type:'grass',text:'Soin'})}
 if(m.target===7)for(const b of m.boosts||[])f.stages[b.stat]=clamp((f.stages[b.stat]||0)+b.change,-6,6);
 if(['protect','detect','endure'].includes(m.slug))r.protectUntil=r.time+1.5;if(['reflect','light-screen','aurora-veil'].includes(m.slug))r.shieldUntil=r.time+12;
 const weather=({'rain-dance':'rain','sunny-day':'sun',sandstorm:'sand',hail:'snow',snowscape:'snow'})[m.slug];if(weather){r.weather=weather;r.weatherUntil=r.time+20}
 if(['stealth-rock','spikes','toxic-spikes','sticky-web'].includes(m.slug)){r.hazards||=[];r.hazards.push({x:r.x,y:r.y,until:r.time+12,move:m});r.hazards=r.hazards.slice(-8)}
 for(const e of targets){if(Math.hypot(e.x-r.x,e.y-r.y)>160)continue;survivalHit(c,e,m,0);for(const b of m.boosts||[])if(m.target!==7){if(['def','spd'].includes(b.stat)&&b.change<0)e.vulnerableUntil=r.time+10;if(['atk','spa'].includes(b.stat)&&b.change<0)e.weakenedUntil=r.time+10;if(b.stat==='speed'&&b.change<0){e.condition='paralysis';e.conditionUntil=r.time+6}}}c.g.audio.attack(m.type)}
export function survivalHit(c,e,raw,amount){const r=c.r,m=moveData(raw||{}),types=c.g.poke(e.key).types;if(m.drain>0&&amount)r.hp=Math.min(r.max,r.hp+amount*m.drain/100);if(m.drain<0&&amount)r.hp=Math.max(1,r.hp-amount*(-m.drain)/100);const chance=m.status?1:(m.ailmentChance||m.effectChance||0)/100;if(e.hp>0&&['burn','poison','paralysis','sleep','freeze'].includes(m.ailment)&&Math.random()<chance){if(m.ailment==='burn'&&types.includes('fire')||m.ailment==='poison'&&types.some(t=>['poison','steel'].includes(t))||m.ailment==='paralysis'&&types.includes('electric'))return;e.condition=m.ailment;e.conditionUntil=r.time+({sleep:3,freeze:2,paralysis:5,burn:7,poison:8})[m.ailment]}if(m.slug==='leech-seed'&&!types.includes('grass')){e.condition='seed';e.conditionUntil=r.time+10}if(m.flinchChance&&Math.random()*100<m.flinchChance){e.condition='sleep';e.conditionUntil=r.time+.5}}
export function survivalStrategyTick(c,dt){const r=c.r;r.hazards=(r.hazards||[]).filter(z=>z.until>r.time);for(const e of r.enemies){e.baseSpeed??=e.speed;const active=e.conditionUntil>r.time;e.speed=e.baseSpeed*(active?['sleep','freeze'].includes(e.condition)?0:e.condition==='paralysis'?.45:1:1);if(active&&['burn','poison','seed'].includes(e.condition)&&e.hp>0){e.dot=(e.dot||0)+dt;if(e.dot>=1){e.dot=0;c.hurt(e,e.max*.04,'typeless');if(e.condition==='seed')r.hp=Math.min(r.max,r.hp+r.max*.02)}}for(const z of r.hazards)if(e.hp>0&&Math.hypot(z.x-e.x,z.y-e.y)<75){if(z.move.slug==='sticky-web'){e.condition='paralysis';e.conditionUntil=r.time+.5}else{e.dot=(e.dot||0)+dt;if(e.dot>=1){e.dot=0;c.hurt(e,e.max*.06,'typeless')}}}}}
export function survivalPower(c,m){const r=c.r,weather=r.weatherUntil>r.time?r.weather:'',boost=stage(r.fighter,m.special?'spa':'atk');return boost*(r.fighter.types.includes(m.type)?1.5:1)*(r.hp<=r.max/3&&({65:'grass',66:'fire',67:'water',68:'bug'})[r.fighter.abilityId]===m.type?1.5:1)*(weather==='rain'?(m.type==='water'?1.5:m.type==='fire'?.5:1):weather==='sun'?(m.type==='fire'?1.5:m.type==='water'?.5:1):1)}
